package pos.ui;
import pos.model.*;import pos.service.PosService;
import javax.swing.*;import javax.swing.table.DefaultTableModel;
import java.awt.*;import java.math.*;import java.nio.file.*;import java.util.*;
public class PosFrame extends JFrame {
    private final PosService svc;private final LinkedHashMap<String,Integer> cart=new LinkedHashMap<>();
    private final DefaultTableModel inventoryModel=new DefaultTableModel(new String[]{"SKU","Product","Price ($)","Stock"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final DefaultTableModel cartModel=new DefaultTableModel(new String[]{"SKU","Product","Qty","Subtotal ($)"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final DefaultTableModel salesModel=new DefaultTableModel(new String[]{"Sale ID","Date","Total ($)","Returned units"},0){public boolean isCellEditable(int r,int c){return false;}};
    private final JLabel totalLabel=new JLabel("Total: $0.00");private final JTextArea receipt=new JTextArea(15,38);private final JTextField cash=new JTextField("20.00",8);
    private final JTable invTable=new JTable(inventoryModel),cartTable=new JTable(cartModel),saleTable=new JTable(salesModel);
    public PosFrame(PosService svc){super("ProjectPos 2026 | Supermarket Checkout");this.svc=svc;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1100,740);setMinimumSize(new Dimension(860,600));setLocationRelativeTo(null);
        JTabbedPane tabs=new JTabbedPane();tabs.add("1  Process Sale",salePanel());tabs.add("2  Handle Returns",returnPanel());tabs.add("3  Inventory",inventoryPanel());add(tabs);refreshAll();}
    private JPanel salePanel(){JPanel p=new JPanel(new BorderLayout(12,12));p.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));
        JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(invTable),new JScrollPane(cartTable));split.setResizeWeight(.5);p.add(split,BorderLayout.CENTER);
        JPanel south=new JPanel(new BorderLayout(6,6));JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));
        JSpinner qty=new JSpinner(new SpinnerNumberModel(1,1,999,1));JButton add=new JButton("Add selected item");add.addActionListener(e->run(()->{int row=invTable.getSelectedRow();if(row<0)throw new IllegalArgumentException("Select an inventory item");String sku=(String)inventoryModel.getValueAt(invTable.convertRowIndexToModel(row),0);int n=(int)qty.getValue();cart.merge(sku,n,Integer::sum);try{svc.total(cart);}catch(RuntimeException ex){cart.merge(sku,-n,Integer::sum);if(cart.get(sku)==0)cart.remove(sku);throw ex;}refreshCart();}));
        JButton clear=new JButton("Clear cart");clear.addActionListener(e->{cart.clear();refreshCart();});
        JButton remove=new JButton("Remove selected cart line");remove.addActionListener(e->{int row=cartTable.getSelectedRow();if(row>=0){cart.remove((String)cartModel.getValueAt(cartTable.convertRowIndexToModel(row),0));refreshCart();}});
        actions.add(new JLabel("Quantity:"));actions.add(qty);actions.add(add);actions.add(remove);actions.add(clear);south.add(actions,BorderLayout.NORTH);
        JPanel pay=new JPanel(new FlowLayout(FlowLayout.LEFT));totalLabel.setFont(totalLabel.getFont().deriveFont(Font.BOLD,18));pay.add(totalLabel);pay.add(new JLabel("   Cash received ($):"));pay.add(cash);JButton checkout=new JButton("Complete cash sale");checkout.addActionListener(e->run(()->{Sale s=svc.checkout(cart,cash.getText());cart.clear();refreshAll();showReceipt(svc.receipt(s));}));pay.add(checkout);south.add(pay,BorderLayout.SOUTH);p.add(south,BorderLayout.SOUTH);return p;}
    private JPanel returnPanel(){JPanel p=new JPanel(new BorderLayout(10,10));p.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));p.add(new JScrollPane(saleTable),BorderLayout.CENTER);
        JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField saleId=new JTextField(9),sku=new JTextField(7);JSpinner count=new JSpinner(new SpinnerNumberModel(1,1,999,1));
        controls.add(new JLabel("Original Sale ID:"));controls.add(saleId);controls.add(new JLabel("SKU:"));controls.add(sku);controls.add(new JLabel("Quantity:"));controls.add(count);
        JButton use=new JButton("Use selected sale");use.addActionListener(e->{int r=saleTable.getSelectedRow();if(r>=0)saleId.setText((String)salesModel.getValueAt(saleTable.convertRowIndexToModel(r),0));});controls.add(use);
        JButton refund=new JButton("Process return & refund");refund.addActionListener(e->run(()->{ReturnRecord r=svc.refund(saleId.getText().trim(),sku.getText().trim(),(int)count.getValue());refreshAll();showReceipt(svc.returnReceipt(r));}));controls.add(refund);p.add(controls,BorderLayout.SOUTH);
        JTextArea help=new JTextArea("Select a sale (or enter its ID), type a SKU purchased in that sale and the quantity.\nReturns restore stock and refund the original unit price. Duplicate/excess returns are blocked.");help.setEditable(false);help.setOpaque(false);p.add(help,BorderLayout.NORTH);return p;}
    private JPanel inventoryPanel(){JPanel p=new JPanel(new BorderLayout(10,10));p.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));JTable table=new JTable(inventoryModel);p.add(new JScrollPane(table),BorderLayout.CENTER);
        JPanel commands=new JPanel(new GridLayout(2,1,4,6));JPanel create=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField sku=new JTextField(7),name=new JTextField(12),price=new JTextField(6);JSpinner stock=new JSpinner(new SpinnerNumberModel(10,0,100000,1));
        create.add(new JLabel("New SKU"));create.add(sku);create.add(new JLabel("Name"));create.add(name);create.add(new JLabel("Price"));create.add(price);create.add(new JLabel("Stock"));create.add(stock);JButton add=new JButton("Create product");add.addActionListener(e->run(()->{svc.addProduct(sku.getText().trim(),name.getText().trim(),price.getText().trim(),(int)stock.getValue());refreshAll();}));create.add(add);commands.add(create);
        JPanel restock=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField existing=new JTextField(8);JSpinner n=new JSpinner(new SpinnerNumberModel(1,1,100000,1));restock.add(new JLabel("Existing SKU"));restock.add(existing);restock.add(new JLabel("Add stock"));restock.add(n);JButton btn=new JButton("Restock");btn.addActionListener(e->run(()->{svc.restock(existing.getText().trim(),(int)n.getValue());refreshAll();}));restock.add(btn);commands.add(restock);p.add(commands,BorderLayout.SOUTH);return p;}
    private void refreshAll(){inventoryModel.setRowCount(0);for(Product x:svc.products())inventoryModel.addRow(new Object[]{x.sku,x.name,x.price,x.quantity()});salesModel.setRowCount(0);for(Sale s:svc.sales()){int units=s.returned.values().stream().mapToInt(Integer::intValue).sum();salesModel.addRow(new Object[]{s.id,s.time.toString().replace('T',' '),s.total,units});}refreshCart();}
    private void refreshCart(){cartModel.setRowCount(0);BigDecimal sum=BigDecimal.ZERO;for(var e:cart.entrySet()){Product x=svc.product(e.getKey());BigDecimal line=x.price.multiply(BigDecimal.valueOf(e.getValue()));sum=sum.add(line);cartModel.addRow(new Object[]{x.sku,x.name,e.getValue(),line});}totalLabel.setText("Total: $"+sum.setScale(2));}
    private void showReceipt(String txt){receipt.setText(txt);receipt.setEditable(false);receipt.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));JButton save=new JButton("Save receipt as TXT");JPanel panel=new JPanel(new BorderLayout());panel.add(new JScrollPane(receipt),BorderLayout.CENTER);panel.add(save,BorderLayout.SOUTH);
        save.addActionListener(e->run(()->{JFileChooser ch=new JFileChooser();ch.setSelectedFile(new java.io.File("receipt.txt"));if(ch.showSaveDialog(this)==JFileChooser.APPROVE_OPTION){try{Files.writeString(ch.getSelectedFile().toPath(),txt);JOptionPane.showMessageDialog(this,"Receipt saved");}catch(Exception ex){throw new IllegalStateException(ex);}}}));JOptionPane.showMessageDialog(this,panel,"Receipt",JOptionPane.PLAIN_MESSAGE);}
    private void run(Runnable fn){try{fn.run();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Action rejected",JOptionPane.ERROR_MESSAGE);}}
}
